-- 7회차 4: 금융업 부채비율 진단 (docs/factors.md 12.9). 국내 최신 유니버스 업종별 종목 수·유동항목 둘 다 빈 수·평균 부채비율. sector_code 는 'KSIC 64992' 처럼 세부 코드라 앞 두 자리로 묶는다(2026-10-02). db-status.yml 의 sql 입력으로 한 번 돌린다
WITH snap AS (SELECT MAX(um.snapshot_date) AS d FROM universe_members um JOIN stocks s ON s.id = um.stock_id WHERE s.country = 'KR'), u AS (SELECT s.id, s.sector_code FROM universe_members um JOIN stocks s ON s.id = um.stock_id WHERE um.included = 1 AND um.snapshot_date = (SELECT d FROM snap) AND s.country = 'KR'), f AS (SELECT u.id, u.sector_code, (SELECT (fi.current_assets IS NULL AND fi.current_liabilities IS NULL) FROM financials fi WHERE fi.stock_id = u.id AND fi.report_code = '11011' ORDER BY fi.fiscal_year DESC, fi.consolidated DESC LIMIT 1) AS cur_null, (SELECT fi.total_liabilities * 1.0 / NULLIF(fi.total_equity, 0) FROM financials fi WHERE fi.stock_id = u.id AND fi.report_code = '11011' ORDER BY fi.fiscal_year DESC, fi.consolidated DESC LIMIT 1) AS dr FROM u) SELECT COALESCE(substr(sector_code, 1, 7), '(없음)') AS sector, COUNT(*) AS n, SUM(cur_null) AS cur_both_null, ROUND(AVG(dr), 2) AS avg_debt_ratio FROM f GROUP BY 1 ORDER BY (substr(sector_code, 1, 7) IN ('KSIC 64', 'KSIC 65', 'KSIC 66')) DESC, n DESC LIMIT 15
